def walk(a,b,p=''):
 if type(a)!=type(b): dif.append((p,'type',type(a).__name__,type(b).__name__)); return
 if isinstance(a,dict):
  for k in sorted(set(a)|set(b)):
   if k not in a or k not in b: dif.append((p+'/'+k,'missing',k in a,k in b))
   else: walk(a[k],b[k],p+'/'+k)
 elif isinstance(a,list):
  if len(a)!=len(b): dif.append((p,'len',len(a),len(b)))
  for i,(x,y) in enumerate(zip(a,b)): walk(x,y,p+f'/{i}')
 elif a!=b: dif.append((p,'value',str(a)[:140],str(b)[:140]))
walk(s,old); print('diff count',len(dif)); print(*dif[:25],sep='\\n')"

